{
  "query": "query { firmaPorEnlace { vigente propuesta { estado } documento { version } } }",
  "variables": {}
}

{
  "query": "mutation($e: FirmarPorEnlaceInput!) { firmarPorEnlace(entrada: $e) { __typename ... on FirmaRegistrada { estado } ... on ErrorFirma { mensaje motivo } } }",
  "variables": {
    "e": {
      "versionDocumento": "{{w7_version}}",
      "aceptaTerminos": true,
      "autorizaCobro": true,
      "modo": "NOMBRE",
      "nombreFirma": "Titular Newman Socio"
    }
  }
}

{
  "query": "mutation { iniciarPago { __typename ... on SesionPago { sesionId urlPago } ... on ErrorPago { mensaje motivo } } }",
  "variables": {}
}

{
  "query": "mutation($s: ID!) { confirmarPago(sesionId: $s) { __typename ... on Poliza { id numero estado } ... on ErrorPago { mensaje motivo } } }",
  "variables": {
    "s": "{{w7_sesion}}"
  }
}

{
  "query": "query { estadoSistema(ventana: \"15m\") { porcentaje color micros { nombre peso responde } apis { nombre color } } }",
  "variables": {}
}
